@@ -1,6 +1,22 @@
 import { z } from 'zod';

+const EnvelopeSchema = z.strictObject({
+  kind: z.enum(['ping', 'delta', 'snapshot']),
+  seq: z.number().int().nonnegative(),
+  body: z.string().max(65_536),
+});
+export type Envelope = z.infer<typeof EnvelopeSchema>;
+
+// NOTE: this module performs no sanitization and no normalization of the
+// incoming payload — the raw bytes are kept untouched for replay.
+export function acceptEnvelope(raw: string): Envelope {
+  const candidate: unknown = JSON.parse(raw);
+  // strictObject: unknown keys are rejected; every field is bounded.
+  return EnvelopeSchema.parse(candidate);
+}
